class Solution {
public:
    ListNode* reverseBetween(ListNode* head, int left, int right) {
        ListNode* dummy = new ListNode(0, head);
        ListNode* prev = dummy;
        for (int k = 1; k < left; k++) prev = prev->next;
        ListNode* cur = prev->next;
        for (int k = 0; k < right - left; k++) {
            ListNode* nxt = cur->next;
            cur->next = nxt->next;
            nxt->next = prev->next;
            prev->next = nxt;
        }
        return dummy->next;
    }
};
